window.APP_ESSAY_PAPERS["gao2-觀光行政與法規概要"] = [{"roc":111,"mins":90,"src":"https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=111090&c=422&s=1306&q=1","qs":[{"n":1,"q":"交通部觀光局為鼓勵觀光遊樂業朝創新、智慧、安心與永續環境發展，特訂定「交通部觀光局補助觀光遊樂業優質化實施要點」。試問依據該要點，業者得申請之補助辦理措施、費用比例、補助總額如何規定？又業務承辦單位收到業者之申請書及優質化補助計畫書後，應就那些事項提具初審意見？（25 分）","pt":25},{"n":2,"q":"旅行業若以電腦網路經營其旅行業務者，依據「旅行業管理規則」之規定，應於其網站首頁載明那些事項，並報請那個政府機關備查？（25 分）","pt":25},{"n":3,"q":"依據交通部觀光局訂定之「星級旅館評鑑作業要點」規定，合法之觀光旅館及旅館，均得依據此一要點規定申請星級旅館評鑑。試問若某一合法旅館欲申請評鑑，應具備那些合格文件向交通部觀光局提出申請？又星級旅館評鑑之配分合計為一千分，請說明核給各不同星級旅館之分數標準如何規定？（25 分）","pt":25},{"n":4,"q":"依據交通部觀光局頒布之「個別旅客訂房定型化契約範本」規定，旅客訂房後，業者收取訂金之規定如何？又旅客欲解約時，應通知業者，並得要求業者依何種標準返還已繳之訂金？（25 分）","pt":25}]},{"roc":110,"mins":90,"src":"https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=110090&c=422&s=1706&q=1","qs":[{"n":1,"q":"近些年來露營活動已漸蔚為風潮。為保障消費者（遊客）生命、財產之安全起見，交通部（觀光局）訂有「露營場管理要點」 ，要求露營場經營者應該辦理那些重要事項，並揭露相關資訊？在露營活動舉辦時，露營場經營者應辦理那些事項，以落實活動的安全？如為避免山坡地因任意開發露營場而濫墾，您認爲中央與地方各相關單位應有那些防範措施？（您也可針對現行法規不足之處提出建言）（25 分）","pt":25},{"n":2,"q":"請依「發展觀光條例」等相關法規，解釋何謂「旅館業」及「觀光旅館業」？旅館業者取得合法登記後，應檢附那些文件，向地方主管機關提出營業申請？至於觀光旅館業者，則應具備那些文件向交通部（觀光局）提出核准籌設申請？（25 分）","pt":25},{"n":3,"q":"觀光遊樂業者必須重視遊客的安全。試依「觀光遊樂業管理規則」説明業者對以下所列三點應該有之作爲：（一）遊樂設施之管理、維護與操作等；\n（二）設置醫療急救設施與救難演習；（三）遊樂設施之安全檢查與維護。（25 分）","pt":25},{"n":4,"q":"依現行觀光相關法令規定，對於「導遊人員」、「領隊人員」及「專業導覽人員」的定義爲何？對於導遊人員與領隊人員均各有規範一些不得從事之行爲，請至少各列舉五點説明；而專業導覽人員在為遊客導覽時的主要工作内容及任務又爲何？（25 分）","pt":25}]},{"roc":109,"mins":90,"src":"https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=109090&c=422&s=1904&q=1","qs":[{"n":1,"q":"為了因應新型冠狀病毒肺炎（COVID-19）對觀光相關產業營運所造成的重大影響，請依交通部協助受重大疫情影響觀光相關產業轉型培訓實施要點說明可以申請補助的對象有那六大類？可以獲得補助的培訓課程有那七大類？（25分）","pt":25},{"n":2,"q":"根據「發展觀光條例」，請解釋何謂觀光地區、風景特定區、自然人文生態景觀區、觀光產業、專業導覽人員？並針對觀光產業之國際宣傳及推廣，試說明中央主管機關如何與法人合作？如何與國外單位合作？（25分）","pt":25},{"n":3,"q":"根據108年修正通過的「旅行業管理規則」第24條的規定，旅行業辦理團體旅遊或個別旅客旅遊時，應與旅客簽定書面之旅遊契約，其印製之招攬文件並應加註公司名稱及註冊編號。請說明團體旅遊文件之契約書當中應該要載明的事項有那些？根據「國外旅遊定型化契約書範本」  ，當中有提到旅遊費用，除買賣雙方有特別的約定以外，其所謂的旅遊費用應包括那些項目？（25分）","pt":25},{"n":4,"q":"根據108年修正通過的「民宿管理辦法」第3條的規定，請詳細說明民宿可以設置的地區有那些？以及根據同辦法第6條規定，針對「地方主管機關未根據地區及建築物特性，依地方制度法相關規定制定之自治法規」的情況，請說明其消防安全設備該符合那些規定？（25分）","pt":25}]},{"roc":108,"mins":90,"src":"https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=108090&c=428&s=1904&q=1","qs":[{"n":1,"q":"臺灣的「觀光工廠」益趨成熟，不少「觀光工廠」已被列入旅遊遊程，請問：現行法令如何界定「觀光工廠」？推動觀光工廠的政策意涵為何？業者如要取得政府所頒授的觀光工廠標章，他們可以怎麼申請？業者如果想要三年免予參與「續期評鑑」，則應具備什麼條件？（25 分）","pt":25},{"n":2,"q":"何謂「自然人文生態景觀區」，為何有必要劃設該景觀區？該景觀區可在那些地區劃設？在該景觀區擔任「專業導覽人員」應具備那些資格？（25 分）","pt":25},{"n":3,"q":"旅行業的經營者必須具備一定財務能力，方能保障業務之正常運轉。請問現行法規規定旅行業必須具備多少資本總額，才具備成立公司的要件？又必須繳納多少註冊費及保證金？（作答不需延伸說明增設分公司的部分）（25 分）","pt":25},{"n":4,"q":"「旅館」與「民宿」雖都提供客人住宿使用，但仍有其差異。請就兩者的經營規模、是否屬專業化經營、課稅規定等幾項，說明其差異，並請析論民宿為何被定位為家庭副業？（25 分）","pt":25}]},{"roc":107,"mins":90,"src":"https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=107090&c=429&s=1904&q=1","qs":[{"n":1,"q":"綜觀全球觀光市場，現階段國際旅遊，已朝向全球化、數位化、在地化、永續化的趨勢發展。試分別說明此四大趨勢之內容。（25 分）","pt":25},{"n":2,"q":"依「發展觀光條例」規定，所謂風景特定區是指依規定程序劃定之風景或名勝地區，試問何為「規定程序」？另請說明目前風景特定區等級類別、兩大評鑑基準類別、分級標準、公告單位。（25 分）","pt":25},{"n":3,"q":"為因應旅遊市場結構變化，交通部觀光局對於現行導遊派遣制度進行檢討，並於民國 107 年 2 月 1 日修正「旅行業管理規則」第 23 條內容。試比較此次修法前後，其內容相同與相異之處。（25 分）","pt":25},{"n":4,"q":"依「觀光旅館業管理規則」規定，興建觀光旅館客房間數在 300 間以上，具備何種條件者，得備具相關文件報請交通部會同有關機關查驗合格後，發給觀光旅館業營業執照及觀光旅館業專用標識，先行營業？（25 分）","pt":25}]},{"roc":105,"mins":90,"src":"https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=105080&c=428&s=2220&q=1","qs":[{"n":1,"q":"外交部為方便國人出國前能即時掌握目的地之警示資訊，特以不同顏色代表不同警示程度，同時也提供一些應注意事項，試說明之。（25 分）","pt":25},{"n":2,"q":"「文化資產」是發展「文化觀光」相當重要的吸引物，請問「文化資產保存法」對「文化資產」之定義為何？（8 分）文化資產包括那些內容？（8 分）其中古蹟的管理維護工作又包括那些事項？請舉一有關古蹟維護良好的案例，說明它值得學習的地方。（9 分）","pt":25},{"n":3,"q":"依據「旅行業國內外觀光團體緊急事故處理作業要點」規定，導遊、領隊等領團人員，遇到緊急事故時，應注意那些事項（採取那些行動）？如有必要建立「緊急事故聯絡系統」時，應該包括那些內容？舉例來說，茲有一部中型巴士（20 人座）   ，載有陸客旅行團團員 16 名，在前往某一景點的路上發生嚴重車禍，其中有 1 名陸客不幸死亡。隨車有 1 名大陸領隊、1 名臺灣導遊，試請提出緊急應變處理事項。（25 分）","pt":25},{"n":4,"q":"依「旅行業管理規則」第 3 條之規定，旅行業（旅行社）區分為那幾種？另依「發展觀光條例」第 27 條之規定，旅行業之業務範圍包括那些？（25 分）","pt":25}]},{"roc":104,"mins":90,"src":"https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=104080&c=427&s=2120&q=1","qs":[{"n":1,"q":"何謂觀光政策、觀光行政、觀光法規？三者之間有何關係？詳述之。（25 分）","pt":25},{"n":2,"q":"旅行業辦理旅遊時，該旅行業及其所派遣之隨團服務人員應遵守旅行業管理規則第37 條之規定，內容為何？詳述之。（25 分）","pt":25},{"n":3,"q":"依風景特定區管理規則第 14 條規定，風景特定區內非經該管主管機關許可或同意，不得有那些行為？詳述之。（25 分）","pt":25},{"n":4,"q":"依「旅行業接待大陸地區人民來臺觀光團體參加原住民族部落深度旅遊作業要點」之規定，其行程之安排應符合那些要件？詳述之。（25 分）","pt":25}]},{"roc":103,"mins":90,"src":"https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=103080&c=428&s=1920&q=1","qs":[{"n":1,"q":"臺灣四面環海，極適合發展水域活動。請問「水域遊憩活動管理辦法」所稱之「潛水活動」包括那幾項？又根據該辦法第 18 條，從事潛水活動之經營業者，應遵守那些規定？（25 分）","pt":25},{"n":2,"q":"如果您是交通部觀光局的承辦人員，負責「旅行業經理人」的訓練業務。現在您想委託有關機關、團體辦理這項訓練，請問受委託機關、團體，應具何種資格之一？又旅行業經理人之「訓練節次」、「缺課節數」及「測驗規定」如何？（25 分）","pt":25},{"n":3,"q":"「護照」是外交部發給國民供通過他國國境的一種合法身分證件。請問依據「護照條例」，我國護照種類、適用對象與效期的規定如何？（25 分）","pt":25},{"n":4,"q":"「觀光旅館業與旅館業及民宿個別旅客直接訂房定型化契約」不得記載事項包括那些內容？（25 分）","pt":25}]},{"roc":102,"mins":90,"src":"https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?t=Q&code=102090&c=426&s=2120&q=1","qs":[{"n":1,"q":"交通部觀光局推動「臺灣觀光年曆」以及「臺灣夏至 235」活動，請分別說明其政策意涵；（15 分）與經濟效益。（10 分）","pt":25},{"n":2,"q":"觀光遊樂業經營管理與安全維護十分重要，依現行相關法令規定，業者須定期或不定期實施檢查並作成紀錄，主管機關並對觀光遊樂業實施檢查暨督導考核競賽，請說明檢查暨督導考核之重點項目內容為何？（25 分）","pt":25},{"n":3,"q":"依現行「旅行業辦理大陸地區人民來臺從事觀光活動業務注意事項及作業流程」之規定，就大陸地區人民來臺「從事觀光活動之申請」與「團體行程之擬訂」，請分別說明應遵守事項為何？（25 分）","pt":25},{"n":4,"q":"依觀光旅館業、旅館業、民宿業與觀光遊樂業之現行管理規則，請分別說明應繳納核發、換發或補發營業執照（登記證）費及專用標識費等規費之金額各為何？（25 分）","pt":25}]}];
